inputs.output_schema:
{
  "type": "object",
  "properties": {
    "prompts": {
      "type": "array",
      "minItems": 4,
      "maxItems": 4,
      "items": {
        "type": "object",
        "properties": {
          "序號": {
            "type": "integer",
            "minimum": 1,
            "maximum": 4
          },
          "提示詞內容": {
            "type": "object",
            "properties": {
              "描述": {
                "type": "string",
                "minLength": 1
              },
              "負向提示詞": {
                "type": "string"
              }
            },
            "required": [
              "描述",
              "負向提示詞"
            ],
            "additionalProperties": false
          },
          "文字內容": {
            "type": "string"
          },
          "人物數量": {
            "type": "integer",
            "minimum": 0,
            "maximum": 2
          },
          "人物陣列": {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "人物1",
                "人物2"
              ]
            },
            "maxItems": 2
          }
        },
        "required": [
          "序號",
          "提示詞內容",
          "文字內容",
          "人物數量",
          "人物陣列"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "prompts"
  ],
  "additionalProperties": false
}
